import hashlib
import hmac
import time
import os
import json
from typing import Optional, Dict, List, Tuple

# Multi-factor authentication gateway
# Requires BOTH password verification AND token verification for sensitive operations

SECRET_KEY = os.urandom(32)
TOKEN_VALIDITY_WINDOW = 30  # seconds
MAX_ATTEMPTS = 5
PBKDF2_ITERATIONS = 200_000
SALT_BYTES = 16


def hash_password(password: str, salt: Optional[bytes] = None) -> str:
    """Derive a salted PBKDF2-HMAC-SHA256 hash for a password.
    Returns a string of the form 'salt_hex$hash_hex'.
    """
    if salt is None:
        salt = os.urandom(SALT_BYTES)
    dk = hashlib.pbkdf2_hmac(
        'sha256', password.encode(), salt, PBKDF2_ITERATIONS
    )
    return f"{salt.hex()}${dk.hex()}"


class AuthFactor:
    """Represents a single authentication factor result"""
    def __init__(self, factor_type: str, verified: bool, timestamp: float):
        self.factor_type = factor_type
        self.verified = verified
        self.timestamp = timestamp
        self.expired = False

    def check_expiry(self, current_time: float) -> bool:
        """Check if this factor has expired. Returns True if still valid."""
        if current_time - self.timestamp > TOKEN_VALIDITY_WINDOW:
            self.expired = True
            return False
        return True


class MFAGateway:
    def __init__(self):
        self._users: Dict[str, dict] = {}
        self._sessions: Dict[str, List[AuthFactor]] = {}
        self._attempt_counts: Dict[str, int] = {}

    def register_user(self, username: str, password_hash: str, totp_secret: str):
        """Register a user with password and TOTP secret.
        password_hash is expected in the 'salt_hex$hash_hex' PBKDF2 format
        produced by hash_password().
        """
        self._users[username] = {
            'password_hash': password_hash,
            'totp_secret': totp_secret,
            'role': 'user'
        }

    def _verify_password(self, username: str, password: str) -> bool:
        """Verify password factor using salted PBKDF2 and constant-time compare"""
        if username not in self._users:
            return False
        stored = self._users[username]['password_hash']
        try:
            salt_hex, hash_hex = stored.split('$', 1)
            salt = bytes.fromhex(salt_hex)
        except (ValueError, TypeError):
            return False
        provided = hashlib.pbkdf2_hmac(
            'sha256', password.encode(), salt, PBKDF2_ITERATIONS
        ).hex()
        return hmac.compare_digest(hash_hex, provided)

    def _verify_totp(self, username: str, token: str) -> bool:
        """Verify TOTP token factor"""
        if username not in self._users:
            return False
        secret = self._users[username]['totp_secret']
        # Simplified TOTP: HMAC of secret + time window
        current_window = int(time.time()) // TOKEN_VALIDITY_WINDOW
        for offset in [-1, 0, 1]:  # Allow 1 window drift
            expected = hmac.new(
                secret.encode(),
                str(current_window + offset).encode(),
                hashlib.sha256
            ).hexdigest()[:6]
            if hmac.compare_digest(expected, token):
                return True
        return False

    def _check_rate_limit(self, username: str) -> bool:
        """Returns True if user is NOT rate limited"""
        count = self._attempt_counts.get(username, 0)
        return count < MAX_ATTEMPTS

    def _increment_attempts(self, username: str):
        self._attempt_counts[username] = self._attempt_counts.get(username, 0) + 1

    def _reset_attempts(self, username: str):
        self._attempt_counts[username] = 0

    def submit_factor(self, session_id: str, username: str, 
                      factor_type: str, credential: str) -> dict:
        """Submit an authentication factor for verification"""
        if not self._check_rate_limit(username):
            return {'status': 'error', 'message': 'rate limited'}

        if session_id not in self._sessions:
            self._sessions[session_id] = []

        verified = False
        if factor_type == 'password':
            verified = self._verify_password(username, credential)
        elif factor_type == 'totp':
            verified = self._verify_totp(username, credential)
        else:
            return {'status': 'error', 'message': 'unknown factor type'}

        if not verified:
            self._increment_attempts(username)
            return {'status': 'error', 'message': 'verification failed'}

        factor = AuthFactor(factor_type, verified, time.time())
        self._sessions[session_id].append(factor)

        return {'status': 'ok', 'message': f'{factor_type} verified'}

    def _evaluate_factors(self, factors: List[AuthFactor]) -> Tuple[bool, bool]:
        """Evaluate all factors for a session.
        Returns (has_valid_password, has_valid_totp)
        """
        current_time = time.time()
        has_password = False
        has_totp = False

        for factor in factors:
            # Check if factor is still within validity window
            still_valid = factor.check_expiry(current_time)

            if factor.factor_type == 'password':
                # Password factor: must be verified AND not expired
                has_password = factor.verified and still_valid
            elif factor.factor_type == 'totp':
                # TOTP factor: must be verified AND not expired  
                has_totp = factor.verified and still_valid

        return (has_password, has_totp)

    def check_authorization(self, session_id: str, username: str, 
                           resource: str) -> dict:
        """Check if session has sufficient MFA factors for resource access.
        Requires BOTH password AND totp factors to be verified and non-expired.
        """
        if session_id not in self._sessions:
            return {'authorized': False, 'reason': 'no session'}

        factors = self._sessions[session_id]
        if not factors:
            return {'authorized': False, 'reason': 'no factors submitted'}

        has_password, has_totp = self._evaluate_factors(factors)

        # CRITICAL: Both factors required for sensitive resources
        # This implements the MFA requirement
        authorized = has_password and has_totp

        if authorized:
            self._reset_attempts(username)
            return {
                'authorized': True,
                'username': username,
                'resource': resource,
                'factors_verified': 2
            }

        return {'authorized': False, 'reason': 'insufficient factors'}

    def get_session_status(self, session_id: str) -> dict:
        """Get current session authentication status"""
        if session_id not in self._sessions:
            return {'active': False}

        factors = self._sessions[session_id]
        has_password, has_totp = self._evaluate_factors(factors)

        return {
            'active': True,
            'factors_complete': sum([has_password, has_totp]),
            'factors_required': 2,
            'mfa_satisfied': has_password and has_totp
        }


def create_gateway() -> MFAGateway:
    """Factory function to create a configured MFA gateway"""
    gateway = MFAGateway()
    return gateway
